from django.db.models.expressions import RawSQL
from .models import Item

def get_sorted_items(order_by_col):
    # Sort items dynamically
    return Item.objects.annotate(
        val=RawSQL(f'select {order_by_col} from item_meta where item_id = id', ())
    ).order_by('val')

